#include <iostream>
#include <vector>
using namespace std;

int main() {
    unsigned N;
    string S;
    cin >> N >> S;

    vector<unsigned> counter(2 * N + 1);  // counter[d + N] = D_j = d 的数量
    unsigned D{N};  // D 的初始值偏移为 N
    ++counter[D];   // D_0 = 0

    unsigned long sum{};  // 小于当前 D 的 counter 之和
    unsigned long ans{};

    for (const auto c : S) {
        if (c == 'A') {
            sum += counter[D++];
        } else if (c == 'B') {
            sum -= counter[--D];
        }
        // C 不影响 D 值

        ++counter[D];
        ans += sum;
    }

    cout << ans << endl;
    return 0;
}

